Here is the commit message:
Network backend: fix bug introduced by 4cb089b

Signed-off-by: Paul Cercueil <paul.cercueil@analog.com>

Here is the root cause:
The bug was caused by using an assignment operator (`=`) instead of a comparison operator (`==`) in the error handling conditions for checking if the error number `errno` equals `EINTR`. This led to incorrect behavior where the condition would always evaluate to true, causing the program to incorrectly handle interrupted system calls in both the `write_all` and `read_all` functions.

Here is the patch:

 static ssize_t write_all(const void *src, size_t len, int fd)
 {
 	uintptr_t ptr = (uintptr_t) src;
 	while (len) {
 		ssize_t ret = send(fd, (const void *) ptr, (int) len, 0);
 		if (ret < 0) {
 #ifdef _WIN32
 			int err = WSAGetLastError();
 #else
 			int err = errno;
 #endif
-			if (err = EINTR)
+			if (err == EINTR)
 				continue;
 			return (ssize_t) -err;
 		}
 		ptr += ret;
 		len -= ret;
 	}
 	return (ssize_t)(ptr - (uintptr_t) src);
 }

 static ssize_t read_all(void *dst, size_t len, int fd)
 {
 	uintptr_t ptr = (uintptr_t) dst;
 	while (len) {
 		ssize_t ret = recv(fd, (void *) ptr, (int) len, 0);
 		if (ret < 0) {
 #ifdef _WIN32
 			int err = WSAGetLastError();
 #else
 			int err = errno;
 #endif
-			if (err = EINTR)
+			if (err == EINTR)
 				continue;
 			return (ssize_t) -err;
 		}
 		if (ret == 0)
 			return -EPIPE;
 		ptr += ret;
 		len -= ret;
 	}
 	return (ssize_t)(ptr - (uintptr_t) dst);
 }



